dunes-script-module.script:
var prototype = RESTHostManager.createHost("ipam");
prototype.url = "https://" + endpoint.get("host");
var host = RESTHostManager.createTransientHostFrom(prototype);
var request = host.createRequest(method, path, body ? JSON.stringify(body) : "");
request.contentType = "application/json";
var response = request.execute();
var result = new Properties();
result.put("statusCode", response.statusCode);
result.put("body", response.contentAsString);
return result;
